        max_prefix = 0
        current_sum = 0
        for x in p:
            current_sum += x
            max_prefix = max(max_prefix, abs(current_sum))
        min_max_prefix = min(min_max_prefix, max_prefix)
    return min_max_prefix

def get_george_price(nums):
    def find_george_sequences(current_nums, current_sum, current_max_prefix):
        if not current_nums:
            return [current_max_prefix]
        min_abs_sum = float('inf')
