            min_abs_sum = min(min_abs_sum, abs(current_sum + x))
        possible_next_elements = [x for x in current_nums if abs(current_sum + x) == min_abs_sum]
        results = []
        for x in possible_next_elements:
            new_nums = list(current_nums)
            new_nums.remove(x)
            results.extend(find_george_sequences(new_nums, current_sum + x, max(current_max_prefix, abs(current_sum + x))))
        return results

